const tz = 'America/Sao_Paulo';
const now = new Date();

// YYYY-MM-DD no fuso de SP
const fmtYMD = new Intl.DateTimeFormat('en-CA', {
  timeZone: tz,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
});

const todaySP = fmtYMD.format(now); // ex: 2026-01-06 (em SP)
const d = new Date(`${todaySP}T00:00:00.000Z`);
d.setUTCDate(d.getUTCDate() ); // ontem (em SP) como "plain date"
const date_query = d.toISOString().slice(0, 10); // YYYY-MM-DD

const [Y, M, D] = date_query.split('-').map(Number);

// offset do timezone (minutos) para um instant
function getTzOffsetMinutes(date, timeZone) {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hourCycle: 'h23',
  });

  const parts = dtf.formatToParts(date);
  const v = {};
  for (const p of parts) if (p.type !== 'literal') v[p.type] = p.value;

  const asUTC = Date.UTC(+v.year, +v.month - 1, +v.day, +v.hour, +v.minute, +v.second);
  return (asUTC - date.getTime()) / 60000;
}

// converte "data/hora no fuso" -> Date UTC real
function zonedToUtcDate(y, m, d, h, mi, s, ms, timeZone) {
  const localAsUTC = Date.UTC(y, m - 1, d, h, mi, s, ms);
  const offset = getTzOffsetMinutes(new Date(localAsUTC), timeZone);
  return new Date(localAsUTC - offset * 60000);
}

const startOfDay = zonedToUtcDate(Y, M, D, 0, 0, 0, 0, tz);
const endOfDay   = zonedToUtcDate(Y, M, D, 23, 59, 59, 999, tz);

// referência no meio do dia só pra evitar “virar” o dia ao formatar
const displayRef = zonedToUtcDate(Y, M, D, 12, 0, 0, 0, tz);

const brDate = displayRef.toLocaleDateString('pt-BR', {
  timeZone: tz,
  weekday: 'long',
  day: '2-digit',
  month: 'long',
  year: 'numeric',
});

