msg += `\u{1F4C5} *Data:* ${data.date_display || 'N/A'}\n`;
msg += `\u{1F4E7} *Assunto:* ${truncate(data.subject, 50)}\n\n`;

// IODEX DESTAQUE
const iodex = benchmarks.find(b => b.symbol === 'IODBZ00') || {};
if (iodex.price) {
  const iodexChange = parseFloat(iodex.change) || 0;
  const iodexEmoji = iodexChange > 0 ? '\u{1F7E2}' : (iodexChange < 0 ? '\u{1F534}' : '\u26AA');
