// QUALITY DIFFERENTIALS
if (differentials.length > 0) {
  msg += `\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n`;
  msg += `\u2697\uFE0F *QUALITY DIFFERENTIALS*\n\n`;
  differentials.slice(0, 4).forEach(d => {
    msg += `\u2022 ${d.name}: US$ ${d.price}\n`;
  });
  if (differentials.length > 4) {
    msg += `_+ ${differentials.length - 4} mais indicadores_\n`;
  }
  msg += '\n';
}

// BALTIC INDICES
if (baltic) {
  msg += `\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n`;
  msg += `\u{1F6A2} *BALTIC INDICES*\n\n`;

  const balticLines = [
    formatBaltic('BDI', baltic.bdi?.value, baltic.bdi?.change, baltic.bdi?.direction),
    formatBaltic('Capesize', baltic.capesize?.value, baltic.capesize?.change, baltic.capesize?.direction),
    formatBaltic('Panamax', baltic.panamax?.value, baltic.panamax?.change, baltic.panamax?.direction),
  ].filter(Boolean);

  balticLines.forEach(line => msg += line + '\n');

  // Rotas principais
  if (baltic.c3?.value) {
    msg += `\u2022 C3 (Tubarao\u2192Qingdao): $${baltic.c3.value}\n`;
  }
  if (baltic.c5?.value) {
    msg += `\u2022 C5 (W.Aus\u2192Qingdao): $${baltic.c5.value}\n`;
