msg += `\u{1F5BC} *Imagem:* ${data.has_image ? '\u2705 Gerada' : '\u274C Falhou'}\n`;

// BOTOES
const buttons = {
  inline_keyboard: [
    [
      { text: '\u2705 Aprovar e Enviar Email', callback_data: `nl_approve_${sessionId}` }
    ],
    [
      { text: '\u{1F5BC} Ver Imagem', callback_data: `nl_view_image_${sessionId}` },
      { text: '\u{1F504} Nova Imagem', callback_data: `nl_regen_image_${sessionId}` }
    ],
    [
      { text: '\u274C Cancelar', callback_data: `nl_cancel_${sessionId}` }
    ]
  ]
};

return [{
  json: {
    chat_id: '8375309778',
    text: msg,
    parse_mode: 'Markdown',
    reply_markup: JSON.stringify(buttons),
